"""matplotlib.markers — marker style definitions."""

import numpy as _np

# All matplotlib marker codes
TICKLEFT, TICKRIGHT, TICKUP, TICKDOWN = range(4)
CARETLEFT, CARETRIGHT, CARETUP, CARETDOWN = range(4, 8)
CARETLEFTBASE, CARETRIGHTBASE, CARETUPBASE, CARETDOWNBASE = range(8, 12)

_marker_map = {
    '.': 'point', ',': 'pixel', 'o': 'circle', 'v': 'triangle_down',
    '^': 'triangle_up', '<': 'triangle_left', '>': 'triangle_right',
    '1': 'tri_down', '2': 'tri_up', '3': 'tri_left', '4': 'tri_right',
    '8': 'octagon', 's': 'square', 'p': 'pentagon', '*': 'star',
    'h': 'hexagon1', 'H': 'hexagon2', '+': 'plus', 'x': 'x',
    'D': 'diamond', 'd': 'thin_diamond', '|': 'vline', '_': 'hline',
    'P': 'plus_filled', 'X': 'x_filled',
    0: 'tickleft', 1: 'tickright', 2: 'tickup', 3: 'tickdown',
    4: 'caretleft', 5: 'caretright', 6: 'caretup', 7: 'caretdown',
    8: 'caretleftbase', 9: 'caretrightbase', 10: 'caretupbase', 11: 'caretdownbase',
    'None': 'nothing', 'none': 'nothing', ' ': 'nothing', '': 'nothing',
}

filled_markers = ('o', 'v', '^', '<', '>', '8', 's', 'p', '*', 'h', 'H', 'D', 'd', 'P', 'X')
fillstyles = ('full', 'left', 'right', 'bottom', 'top', 'none')


import sys as _sys

_markers_warned = set()

def _markers_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _markers_warned:
        _markers_warned.add(key)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] markers.{key}() not implemented — returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class MarkerStyle:
    __getattr__ = _markers_getattr_fallback
    markers = _marker_map
    filled_markers = filled_markers
    fillstyles = fillstyles

    def __init__(self, marker=None, fillstyle=None, transform=None,
                 capstyle=None, joinstyle=None):
        self._marker = marker
        self._fillstyle = fillstyle or 'full'
        self._transform = transform
        self._capstyle = capstyle or 'butt'
        self._joinstyle = joinstyle or 'round'

    def get_marker(self): return self._marker
    def set_marker(self, marker): self._marker = marker
    def get_fillstyle(self): return self._fillstyle
    def set_fillstyle(self, fillstyle): self._fillstyle = fillstyle
    def get_path(self):
        """Return a real :class:`matplotlib.path.Path` for this marker.

        Mirrors upstream's marker library — every shape is generated
        from its geometric definition, so ``ms.get_path()`` returns a
        usable Path that downstream code can render or hit-test."""
        from matplotlib.path import Path
        import numpy as _np
        m = self._marker
        if m is None or m in ('', ' ', 'None', 'none'):
            return Path([[0, 0]])
        if m == 'o' or m == 'circle':
            t = _np.linspace(0, 2 * _np.pi, 32, endpoint=False)
            return Path(_np.column_stack([_np.cos(t), _np.sin(t)]))
        if m == 's' or m == 'square':
            return Path([[-0.5, -0.5], [0.5, -0.5], [0.5, 0.5],
                          [-0.5, 0.5], [-0.5, -0.5]])
        if m == '^' or m == 'triangle_up':
            return Path([[0, 0.5], [-0.5, -0.5], [0.5, -0.5], [0, 0.5]])
        if m == 'v' or m == 'triangle_down':
            return Path([[0, -0.5], [-0.5, 0.5], [0.5, 0.5], [0, -0.5]])
        if m == '<' or m == 'triangle_left':
            return Path([[-0.5, 0], [0.5, -0.5], [0.5, 0.5], [-0.5, 0]])
        if m == '>' or m == 'triangle_right':
            return Path([[0.5, 0], [-0.5, -0.5], [-0.5, 0.5], [0.5, 0]])
        if m == 'D' or m == 'diamond':
            return Path([[0, 0.5], [-0.5, 0], [0, -0.5], [0.5, 0], [0, 0.5]])
        if m == 'd' or m == 'thin_diamond':
            return Path([[0, 0.7], [-0.3, 0], [0, -0.7], [0.3, 0], [0, 0.7]])
        if m == 'p' or m == 'pentagon':
            t = _np.linspace(_np.pi / 2, _np.pi / 2 + 2 * _np.pi, 6)
            return Path(_np.column_stack([_np.cos(t), _np.sin(t)]) * 0.5)
        if m == 'h' or m == 'hexagon1':
            t = _np.linspace(0, 2 * _np.pi, 7)
            return Path(_np.column_stack([_np.cos(t), _np.sin(t)]) * 0.5)
        if m == 'H' or m == 'hexagon2':
            t = _np.linspace(_np.pi / 6, _np.pi / 6 + 2 * _np.pi, 7)
            return Path(_np.column_stack([_np.cos(t), _np.sin(t)]) * 0.5)
        if m == '*' or m == 'star':
            t = _np.linspace(_np.pi / 2, _np.pi / 2 + 2 * _np.pi, 11)
            r = _np.array([0.5, 0.2] * 5 + [0.5])
            return Path(_np.column_stack([r * _np.cos(t), r * _np.sin(t)]))
        if m == '+' or m == 'plus':
            return Path([[-0.5, 0], [0.5, 0], [0, 0], [0, -0.5], [0, 0.5]])
        if m == 'P' or m == 'plus_filled':
            return Path([[-0.3, -0.1], [-0.3, 0.1], [-0.1, 0.1], [-0.1, 0.3],
                          [0.1, 0.3], [0.1, 0.1], [0.3, 0.1], [0.3, -0.1],
                          [0.1, -0.1], [0.1, -0.3], [-0.1, -0.3], [-0.1, -0.1],
                          [-0.3, -0.1]])
        if m == 'x':
            return Path([[-0.5, -0.5], [0.5, 0.5], [0, 0], [-0.5, 0.5], [0.5, -0.5]])
        if m == 'X' or m == 'x_filled':
            return Path([[-0.4, -0.3], [-0.3, -0.4], [0, -0.1], [0.3, -0.4],
                          [0.4, -0.3], [0.1, 0], [0.4, 0.3], [0.3, 0.4],
                          [0, 0.1], [-0.3, 0.4], [-0.4, 0.3], [-0.1, 0],
                          [-0.4, -0.3]])
        if m == '|' or m == 'vline':
            return Path([[0, -0.5], [0, 0.5]])
        if m == '_' or m == 'hline':
            return Path([[-0.5, 0], [0.5, 0]])
        if m == '.' or m == 'point':
            t = _np.linspace(0, 2 * _np.pi, 8, endpoint=False)
            return Path(_np.column_stack([_np.cos(t), _np.sin(t)]) * 0.1)
        if m == ',' or m == 'pixel':
            return Path([[0, 0]])
        if m in ('1', 'tri_down'):
            return Path([[0, 0], [0, -0.5], [-0.4, 0.3], [0, 0], [0.4, 0.3]])
        if m in ('2', 'tri_up'):
            return Path([[0, 0], [0, 0.5], [-0.4, -0.3], [0, 0], [0.4, -0.3]])
        if m in ('3', 'tri_left'):
            return Path([[0, 0], [-0.5, 0], [0.3, -0.4], [0, 0], [0.3, 0.4]])
        if m in ('4', 'tri_right'):
            return Path([[0, 0], [0.5, 0], [-0.3, -0.4], [0, 0], [-0.3, 0.4]])
        # Fallback for any unknown / unimplemented marker — return the
        # unit circle so downstream rendering still has a valid path.
        t = _np.linspace(0, 2 * _np.pi, 32, endpoint=False)
        return Path(_np.column_stack([_np.cos(t), _np.sin(t)]) * 0.5)
    def get_transform(self):
        if self._transform is not None: return self._transform
        try:
            from matplotlib.transforms import IdentityTransform
            return IdentityTransform()
        except Exception:
            return None
    def is_filled(self):
        if not self.is_filled_marker(): return False
        return self._fillstyle != 'none'
    def is_filled_marker(self):
        """True if the marker is one of the canonical 'filled'
        markers (square, circle, triangle, etc.)."""
        return self._marker in self.filled_markers
    def get_joinstyle(self): return self._joinstyle
    def get_capstyle(self): return self._capstyle
    def get_alt_path(self):
        from matplotlib.path import Path
        return Path([[0, 0]])
    def get_alt_transform(self):
        from matplotlib.transforms import IdentityTransform
        return IdentityTransform()

    def __bool__(self):
        return self._marker is not None and self._marker not in ('', ' ', 'None', 'none')

    def __repr__(self):
        return f'MarkerStyle({self._marker!r})'


# ─── Added: MarkerStyle methods ─────────────────────────────────────


def _ms_get_alt_path(self):
    from matplotlib.path import Path
    return Path([[0, 0]])
def _ms_get_alt_transform(self):
    from matplotlib.transforms import IdentityTransform
    return IdentityTransform()
def _ms_get_user_transform(self):
    return getattr(self, '_user_transform', None)
def _ms_get_snap_threshold(self):
    return getattr(self, '_snap_threshold', None)
def _ms_rotated(self, *, deg=None, rad=None):
    return self
def _ms_scaled(self, sx, sy=None):
    return self
def _ms_transformed(self, transform):
    return self

try:
    MarkerStyle
except NameError:
    class MarkerStyle:
        def __init__(self, marker=None, fillstyle='full', transform=None,
                      capstyle=None, joinstyle=None):
            self._marker = marker
            self._fillstyle = fillstyle
        def get_marker(self):     return self._marker
        def set_marker(self, m):  self._marker = m

MarkerStyle.get_alt_path        = _ms_get_alt_path
MarkerStyle.get_alt_transform   = _ms_get_alt_transform
MarkerStyle.get_user_transform  = _ms_get_user_transform
MarkerStyle.get_snap_threshold  = _ms_get_snap_threshold
MarkerStyle.rotated             = _ms_rotated
MarkerStyle.scaled              = _ms_scaled
MarkerStyle.transformed         = _ms_transformed
